  if ((tensor == nullptr) || (tensor->data_type_size == 0U)) {
    return false;
  }
  data_type_size = tensor->data_type_size;
  return true;
}

bool IsDynamicExprBytes(const Expr &repeat_expr, uint32_t data_type_size) {
  if (data_type_size == 0U) {
    return false;
  }
