25	// 表征轴优先级的图结构， a->b表示a的优先级高于b
26	class ArgPriorityGraph {
27	 public:
28	  // 构造函数初始化
29	  explicit ArgPriorityGraph() = default;
30	  explicit ArgPriorityGraph(size_t n)
31	      : vertex_count_(n),
32	        adj_list_(n + 1),  // 顶点编号从1开始
33	        in_degree_(n + 1, 0) {}
34	
35	  // 检查是否会创建环（模拟添加边后检查）
36	  bool WillCreateCycle(size_t from, size_t to) {
37	    std::vector<bool> visited(vertex_count_ + 1, false);
38	    std::queue<size_t> bfs_queue;
39	
40	    // 模拟添加边后的状态，从to出发检测是否能回到from
41	    bfs_queue.push(to);
42	    while (!bfs_queue.empty()) {
43	      size_t current = bfs_queue.front();
44	      bfs_queue.pop();
45	
46	      for (size_t neighbor : adj_list_[current]) {
47	        if (neighbor == from) {
48	          return true;  // 发现环
49	        }
50	        if (!visited[neighbor]) {
51	          visited[neighbor] = true;
52	          bfs_queue.push(neighbor);
53	        }
54	      }
55	    }
56	    return false;
57	  }
58	
59	  // 添加有向边
60	  bool AddEdge(size_t from, size_t to) {
61	    // 参数检查
62	    if (from == 0u || from > vertex_count_ || to == 0u || to > vertex_count_) {
63	      GELOGE(af::FAILED, "node id invalid");
64	      return false;
65	    }
66	
67	    // 检查边是否已存在
68	    auto &edges = adj_list_[from];
69	    if (std::find(edges.begin(), edges.end(), to) != edges.end()) {
70	      return true;  // 边已存在，直接返回
71	    }
72	
73	    // 成环检测
74	    if (WillCreateCycle(from, to)) {
75	      GELOGI("Create Cycle from %zu to %zu, refuse to add edge", from, to);
76	      return true;  // 添加会导致环，拒绝操作
77	    }
78	
79	    // 执行添加
80	    edges.push_back(to);
81	    in_degree_[to]++;
82	    return true;
83	  }
84	
85	  // 拓扑排序主入口
86	  std::vector<size_t> TopologicalSort(bool use_bfs = true) {
87	    return use_bfs ? KahnAlgorithm() : DfsPostOrder();
88	  }
89	
